-- Migration 0038 (spec 14.30): Southeast Asia, the ninth home region (regions step 1 and 2 for it).
--
-- What changes:
--  * 59 new airports: Thailand 9 (Don Mueang, Chiang Mai, Krabi, Samui...), Malaysia 9 (Penang, Kota Kinabalu,
--    Kuching...), Indonesia 15 (Surabaya, Makassar, Medan, Yogyakarta...), the Philippines 12 (Cebu, Davao, Clark,
--    Bohol...), Vietnam 8 (Nha Trang, Phu Quoc, Hai Phong...), Cambodia 2 (Phnom Penh's new Techo airport, Siem Reap),
--    Laos 2, Myanmar 1 and Brunei 1. The 11 Southeast Asian airports already in the game (Singapore, Bangkok, Kuala
--    Lumpur, Jakarta, Manila, Ho Chi Minh City, Hanoi, Bali, Phuket, Da Nang, Yangon) become home airports of the new
--    region (airports.home 'southeast_asia'), 10 of them with published figures. 70 home airports in all; passenger
--    totals published for 45 of them (pax_src V: Changi, AOT, MAHB, InJourney, CAAP and ACV figures for 2023-2025),
--    the rest estimates (pax_src G).
--  * Every market outside India is rebuilt by tools/build_regions.py (refresh), with the new inputs in supabase/seed:
--    29624 markets. Southeast Asia's own pairs (Singapore-Kuala Lumpur, Hanoi-Ho Chi Minh City...) are new;
--    the other regions' markets change a little, since Southeast Asia's travellers now count in full and Japan, Korea,
--    Australia and Russia send more of theirs there (regions_model.csv, zone_affinity.csv, country_affinity.csv,
--    longhaul_hubs.csv). Refused if any route flies a market outside India (none does: no world is based outside India).
--  * public.regions row 'southeast_asia' (G): the Singapore dollar (S$1 = Rs 70 at the game's reference rates), fuel
--    0.8, pay 1.2 and charges 1.0 against India's, growth x0.85, price sensitivity as India's (x1.1 left the region
--    12 points behind India in a season run), currency swings x0.7 with few shocks and a slow rise, loans 4.5 points
--    cheaper, pilots for hire x0.9, registrations 9V-.
--  * world_options: region Southeast Asia, not open yet (step 3 opens regions), with its passenger rights and tax.
--  * airports.home must name a row of public.regions (a foreign key in place of 0035's list of eight).
--  * game.refresh_regions() works out every region's price level and demand factor again.
--  * India's 6,584 markets and 93 airports are not touched. No function changes.

insert into public.regions (key, name, currency, symbol, unit_inr, style, fuel_level, pay_level, charge_level, growth_mult,
                            price_sens_mult, fx_vol_mult, fx_event_mult, fx_drift_year, loan_rate_delta, pilot_pool_mult, note, reg_prefix,
                            price_level, demand_mult) values
('southeast_asia', 'Southeast Asia', 'SGD', 'S$', 70, 'western', 0.8, 1.2, 1.0, 0.85, 1.0, 0.7, 0.2, -0.01, -4.5, 0.9,
 'Islands where flying is the only way across, low-cost airlines with half the seats, leisure islands fed from Australia, China, Korea and Japan, and Singapore as the hub; a steady currency that rises slowly.',
 '9V-', 1, 1);

insert into public.world_options (setting, option, sort, label, blurb, vals, available, is_default) values
('region', 'southeast_asia', 9, 'Southeast Asia', 'coming',
 '{"cancel_notice_days": 3, "cancel_km_1": 1500, "cancel_km_2": 3500, "cancel_comp_1_inr": 3000, "cancel_comp_2_inr": 3000, "cancel_comp_3_inr": 3000, "cancel_cap_fare_mult": 99, "cancel_fare_share": 0, "denied_comp_inr": 5000, "denied_fare_mult": 0, "tax_rate": 0.21, "cash_interest_year": 0.03}',
 false, false);

-- a home region is any row of public.regions (0035 listed eight)
alter table public.airports drop constraint airports_home_check;
alter table public.airports add constraint airports_home_fkey foreign key (home) references public.regions (key);

insert into public.airports (iata,city,country,region,is_india,lat,lon,pax_m,pax_src,intl_share,od_share,home,biz_idx,tour_idx,slot_cap,runway_class) values
